import * as Store from './storage.js';
import * as Sync from './sync.js';
import * as Features from './features.js';
import * as Ops from './ops.js';
import {compressProductPhoto,editDocumentPhoto} from './photo-tools.js';
import {VERSION,uid,localDate,refKey,number,estimateLines,dailyStats,parseOrderText,toCSV,validateFamilyParent} from './core.js';
import {state,esc,icon,fmt,btn,nav,badge,field,check,modal,modalForm,closeModal,toast,formError,download,jsonDownload,pdfReport,dateLabel,timestampLabel} from './ui.js';
import {loadCatalogue,products,families,familyOptions,findProduct,findProducts,productName,recordLabel,pendingStatus} from './model.js';
import {renderView,titles} from './views.js';
import {renderMobileNav,mobileTools,enhanceMobileView,installMobileViewport} from './mobile.js';

let renderPending=false,restoreInput,installPrompt,autoSyncTimer,formSaving=false;
const dataObject=form=>Object.fromEntries(new FormData(form));
const isoNow=()=>new Date().toISOString();
const getRaw=(type,id)=>Store.get(type,id);
const attrId=id=>`data-id="${esc(id)}"`;

function render(){
  const active=document.activeElement,id=active?.id,selection=active?.selectionStart;
  const main=document.querySelector('#main');main.innerHTML=state.route==='more'?mobileTools():['unknowns','journal'].includes(state.route)?Ops.renderOpsView():renderView();enhanceMobileView(main,state.route,(Store.settings().homeShortcuts||[]).map(id=>Ops.SHORTCUTS.find(([key])=>key===id)).filter(Boolean).map(([action,title,hint,glyph])=>[action,glyph,title,hint]));Ops.enhanceOps(main,state.route);document.querySelector('#mobile-nav').innerHTML=renderMobileNav(state.route,Store.list('pending').filter(p=>p.status!=='done').length);document.querySelector('#breadcrumb').textContent=titles[state.route]||titles.home;
  document.title=(titles[state.route]||'Accueil')+' · EK Logistique';
  const avatar=Store.settings().name.split(/\s+/).map(s=>s[0]).slice(0,2).join('').toUpperCase();document.querySelector('#avatar').textContent=avatar;
  document.body.classList.toggle('beginner',Store.settings().beginner);
  document.querySelector('#app-version').textContent=VERSION;const demo=document.querySelector('#demo-banner');demo.hidden=!Store.isDemo();demo.className='demo-banner';demo.innerHTML=Store.isDemo()?`<strong>Mode démonstration</strong><span>Des exemples séparés de vos données.</span>${btn('Revenir à mes données','exit-demo','','small')}`:'';
  updateNetwork();if(state.route==='codes')Features.showBarcode();
  if(id){const next=document.getElementById(id);if(next&&document.querySelector('#main').contains(next)){next.focus({preventScroll:true});if(typeof selection==='number'&&['text','search'].includes(next.type))next.setSelectionRange(selection,selection);}}
}
function queueRender(){if(state.route==='scan'||renderPending)return;renderPending=true;queueMicrotask(()=>{renderPending=false;render();});}
function navigate(route,params={}){void Ops.persistDraft();if(!titles[route])route='home';if(state.route!==route){Features.stopCamera();Features.stopDictation();state.query='';state.filter='all';state.page=0;}state.route=route;if(params.value)state.codeValue=params.value;if(location.hash!=='#'+route)history.pushState(null,'','#'+route);closeModal();render();window.scrollTo({top:0,behavior:'instant'});document.querySelector('#main').focus({preventScroll:true});}
function updateNetwork(){const el=document.querySelector('#network');el.classList.toggle('offline',!navigator.onLine);el.innerHTML=`<i></i>${!navigator.onLine?'Hors connexion':Sync.connected()?'Google connecté':'Sur cet appareil'}`;}
function wrapAction(fn){return Promise.resolve().then(fn).catch(e=>toast(e.message||String(e),true));}

function welcome(role=Store.settings().profile){state.formRole=role;modal('Bienvenue dans EK Logistique',`<div class="onboarding-logo">${icon('box')} Votre espace de travail</div><p class="dialog-intro">Retrouvez vos codes-barres, vos commandes et vos repères de stock. Choisissez votre point de départ ; vous pourrez en changer à tout moment.</p><div class="role-select"><button class="role-option ${role==='preparer'?'selected':''}" data-action="onboard-role" data-role="preparer">${icon('box')}<div><h3>Préparer les commandes</h3><p>Codes, réassorts et pickings.</p></div></button><button class="role-option ${role==='stock'?'selected':''}" data-action="onboard-role" data-role="stock">${icon('layers')}<div><h3>Gérer le stock</h3><p>Emplacements, contrôles et écarts.</p></div></button></div><form data-form="onboarding"><div class="form-grid">${field('name','Votre prénom',Store.settings().name,{required:true,attrs:'maxlength="60"'})}${field('goal','Objectif de pickings',Store.settings().goal,{type:'number',required:true})}</div><div class="form-actions">${btn('Essayer les exemples','enter-demo','','')}<button class="btn primary" type="submit">Commencer ${icon('arrow')}</button></div></form><p class="hint">Les données de travail restent vides au départ. La démonstration est séparée.</p>`);}
function pendingForm(row={}){modalForm('pending',`${field('orderNumber','Numéro de commande',row.orderNumber||'',{required:true,code:true,voice:true})}${field('sku','Référence manquante',row.sku||'',{required:true,code:true,voice:true})}${field('location','Casier / emplacement',row.location||'',{code:true,voice:true})}${field('quantity','Quantité manquante',row.quantity??'',{type:'number',required:true})}${field('received','Quantité déjà reçue',row.received??0,{type:'number'})}${field('assignee','Personne sollicitée',row.assignee||'JC',{voice:true})}${field('priority','Priorité',row.priority||'normal',{select:[{value:'normal',label:'Normale'},{value:'urgent',label:'Prioritaire'}]})}${field('status','État du suivi',row.status||'waiting',{select:Object.entries(pendingStatus).map(([value,o])=>({value,label:o.label}))})}${field('notes','Précisions',row.notes||'',{textarea:true,voice:true,full:true})}`,{name:'pending',id:row.id,title:row.id?'Modifier l’attente de réassort':'Noter une référence manquante',intro:'Une ligne relie une référence à une commande. La réception du réassort et la fin de la commande sont deux étapes distinctes.'});}
function productForm(p={}){state.draftProductPhotoId=null;modalForm('product',`${field('sku','Référence interne',p.sku||'',{required:true,code:true,voice:true})}${field('barcode','Code EAN ou autre code lu',p.barcode||'',{code:true,voice:true})}${field('name','Dénomination du produit',p.name||'',{required:true,voice:true,full:true})}${field('familyId','Famille',p.familyId||'',{select:familyOptions()})}${field('unitsPerPick','Unités prises à chaque picking',p.unitsPerPick??'',{type:'number',hint:'Laissez vide si vous ne connaissez pas le conditionnement. Aucune règle n’est déduite du catalogue.'})}${field('location','Emplacement habituel',p.location||'',{code:true,voice:true})}${field('aliases','Autres noms pour la recherche',p.aliases||'',{full:true,hint:'Ex. carnet rose, petit cahier'})}${field('notes','Repères utiles',p.notes||'',{textarea:true,voice:true,full:true})}<div class="field full"><label for="product-photo">Photo du produit ou de l’emballage</label><input id="product-photo" name="productPhoto" type="file" accept="image/*" capture="environment">${p.photoId?`<img class="product-photo" data-product-photo="${esc(p.photoId)}" alt="Photo du produit" hidden>${check('removePhoto','Retirer la photo actuelle',false)}`:''}<p class="hint">Photo facultative. Elle est conservée sur cet appareil et incluse dans les sauvegardes.</p></div>`,{id:p.id,title:p.id?'Compléter la référence':'Ajouter une référence',intro:'Gardez les chiffres et les zéros de la référence tels qu’ils apparaissent. Les règles de prise sont à confirmer dans l’entrepôt.'});void Ops.hydratePhotos();}
function familyForm(f={}){modalForm('family',`${field('name','Nom de la famille',f.name||'',{required:true,voice:true,full:true})}${field('parentId','Famille parente',f.parentId||'',{select:[{value:'',label:'Aucune — famille principale'},...families(true).filter(o=>o.id!==f.id).map(o=>({value:o.id,label:o.name}))],full:true})}<div class="field full">${check('active','Proposer cette famille dans les nouvelles fiches',f.active!==false)}</div>`,{id:f.id,title:f.id?'Modifier une famille':'Nouvelle famille'});}
function locationForm(r={}){modalForm('location',`${field('name','Nom / code de l’emplacement',r.name||'',{required:true,voice:true,code:true,full:true})}${field('aisle','Allée',r.aisle||'',{voice:true,code:true})}${field('level','Niveau',r.level||'',{voice:true})}${field('zone','Zone',r.zone||'Picking',{select:['Picking','Réserve','Réception','Expédition','Contrôle','Autre']})}${field('notes','Repères et accès',r.notes||'',{textarea:true,voice:true,full:true})}`,{id:r.id,title:r.id?'Modifier l’emplacement':'Ajouter un emplacement'});}
function movementForm(){modalForm('movement',`${field('sku','Référence déplacée','',{required:true,voice:true,code:true,full:true})}${field('from','Emplacement de départ','',{required:true,voice:true,code:true})}${field('to','Emplacement d’arrivée','',{required:true,voice:true,code:true})}${field('quantity','Quantité déplacée','',{type:'number',required:true})}${field('reason','Motif','Regroupement',{select:['Regroupement','Réassort','Changement de casier','Mise en réserve','Correction d’emplacement','Autre']})}${field('notes','Précisions','',{textarea:true,voice:true,full:true})}`,{title:'Noter un transfert',intro:'Cette fiche conserve votre trace du mouvement. Son enregistrement dans le stock officiel reste à faire avec l’outil de l’entrepôt.'});}
function countForm(r={},empty=false){modalForm('count',`${field('session','Session de contrôle',r.session||('Contrôle du '+dateLabel(state.date)),{required:true,voice:true,full:true})}${field('date','Date du comptage',r.date||state.date,{type:'date',required:true})}${field('location','Emplacement contrôlé',r.location||'',{required:true,voice:true,code:true})}${field('sku','Référence trouvée',r.sku||'',{voice:true,code:true,hint:empty?'Facultatif si l’emplacement est réellement vide.':'Facultatif pour un contrôle global du casier.'})}${field('counted','Quantité comptée',r.counted??'',{type:'number',required:true})}${field('expected','Quantité attendue',empty?0:r.expected??'',{type:'number',hint:'Facultatif : le rapprochement peut être réalisé plus tard.'})}${field('notes','Observations',r.notes||'',{textarea:true,voice:true,full:true})}<input type="hidden" name="kind" value="${esc(r.kind||(empty?'empty':'count'))}">`,{id:r.id,title:empty?'Contrôler un emplacement annoncé vide':r.id?'Corriger un comptage':'Nouveau comptage',intro:empty?'Un emplacement annoncé vide a une quantité attendue égale à zéro. Notez ce que vous constatez réellement.':'Comptez la quantité physique. La différence avec le stock attendu apparaîtra dans votre liste.'});}
function replenishmentForm(r={}){modalForm('replenishment',`${field('sku','Référence',r.sku||'',{required:true,voice:true,code:true})}${field('location','Casier',r.location||'',{required:true,voice:true,code:true})}${field('min','Stock minimum',r.min??'',{type:'number',required:true})}${field('economic','Niveau économique',r.economic??'',{type:'number',required:true})}${field('max','Stock maximum',r.max??'',{type:'number',required:true})}${field('current','Dernière quantité constatée',r.current??'',{type:'number',hint:'Facultatif. La suggestion se base seulement sur ce constat.'})}${field('notes','Règle ou précision',r.notes||'',{textarea:true,voice:true,full:true})}`,{id:r.id,title:r.id?'Modifier les seuils':'Ajouter des seuils de réassort',intro:'Ces valeurs sont un suivi de vos réglages ; le paramétrage dans Velocity reste indépendant.'});}
function issueForm(r={}){modalForm('issue',`${field('kind','Type de situation',r.kind||'Emplacement vide',{select:['Emplacement vide','Quantité différente','Mauvais emplacement','Produit abîmé','Référence introuvable','Retour en inventaire','Autre'],full:true})}${field('sku','Référence concernée',r.sku||'',{code:true,voice:true})}${field('location','Emplacement',r.location||'',{code:true,voice:true})}${field('expected','Quantité attendue',r.expected??'',{type:'number'})}${field('found','Quantité trouvée',r.found??'',{type:'number'})}${field('assignee','À suivre avec',r.assignee||'JC',{voice:true})}${field('status','Statut',r.status||'open',{select:[{value:'open',label:'À traiter'},{value:'progress',label:'En cours'},{value:'resolved',label:'Résolu'}]})}${field('notes','Faits et précisions',r.notes||'',{required:true,textarea:true,voice:true,full:true})}<div class="field full"><label for="issue-photo">Ajouter une photo</label><input name="photo" id="issue-photo" type="file" accept="image/*" capture="environment">${r.photoId?'<p class="hint">Une photo est déjà associée. Un nouveau choix la remplacera sur cette fiche.</p>':''}</div>`,{id:r.id,title:r.id?'Compléter le signalement':'Signaler un écart'});}
function dayCorrection(){const stats=dailyStats(state.date,Store.list('orders'),Store.list('days'),Store.settings().goal);modalForm('day-correction',`${field('date','Journée concernée',state.date,{type:'date',required:true,full:true})}${field('manualTotal','Total à retenir pour la journée',stats.correction?.manualTotal??(stats.hasData?stats.total:''),{type:'number',required:true,full:true})}${field('reason','Source ou raison de la correction',stats.correction?.reason||'',{required:true,textarea:true,voice:true,full:true,placeholder:'Ex. Chiffre communiqué par Adrien'})}`,{id:stats.correction?.id,title:'Corriger un total journalier',intro:'La valeur initiale reste dans l’historique. Le graphique utilisera le total corrigé, y compris pour une journée passée.'});}

function orderForm(order){state.selectedOrder=order||null;state.orderLines=order?.lines?.map(l=>({...l}))||[{sku:'',quantity:'',pack:'',pickingOverride:''}];state.orderPhotos=[];state.draftPhotoIds=[];state.orderText='';
  modal('Enregistrer une commande',`<p class="dialog-intro">Photographiez la feuille ou saisissez ses lignes. La lecture photo propose un texte à vérifier ; elle ne valide pas les quantités à votre place.</p><form data-form="order" data-id="${esc(order?.id||'')}"><div class="form-grid">${field('number','Numéro de commande',order?.number||'',{required:true,code:true,voice:true})}${field('date','Date de réalisation',order?.date||state.date,{type:'date',required:true})}</div><details ${order?'':'open'}><summary>Ajouter une photo ou coller un texte</summary><div class="upload-zone section-gap">${icon('camera')}<p>Cadrez toute la feuille, à plat, sans reflet.</p><label class="sr-only" for="order-photos">Photos de la commande</label><input type="file" accept="image/*" capture="environment" multiple id="order-photos" data-file-action="order-photos">${Store.isDemo()?btn("Essayer la feuille d’exemple","ocr-example","camera","small section-gap"):""}</div><p class="ocr-progress" id="ocr-progress" role="status"></p><div class="field section-gap"><label for="order-raw-text">Texte à relire ou liste à coller</label><textarea id="order-raw-text" rows="5" placeholder="Référence ; quantité ; unités par prise&#10;76013491 ; 12 ; 4"></textarea><p class="hint">Une ligne par référence, séparateurs « ; ». Une photo peut demander un peu de temps pour la première lecture.</p></div>${btn('Extraire les lignes du texte','parse-order-text','list','small section-gap')}</details><h3 class="modal-subheading">Vérifier les lignes</h3><div id="order-lines" class="order-line-list"></div><div class="actions section-gap">${btn('Ajouter une ligne','add-order-line','plus','small')}${btn('Recalculer','recalculate-order','chart','small')}</div><div id="order-estimate"></div><div class="form-grid section-gap">${field('notes','Précisions',order?.notes||'',{textarea:true,voice:true,full:true})}<div class="field full">${check('checked','J’ai vérifié les références, les quantités et le numéro de commande.',false,'required')}</div><div class="field full">${check('completed','La commande est terminée et doit être comptée sur cette journée.',true,'required')}</div></div><div class="error-message" data-form-error role="alert" hidden></div><div class="form-actions">${btn('Annuler','close-dialog')}<button class="btn primary" type="submit">${icon('check')}Enregistrer la commande</button></div></form>`,true);renderOrderLines();updateOrderEstimate();}
function readOrderLines(){const rows=[...document.querySelectorAll('#order-lines .order-line')];return rows.map(tr=>Object.fromEntries([...tr.querySelectorAll('[data-line-field]')].map(i=>[i.dataset.lineField,i.value])));}
function fillLinePackaging(input){const row=input.closest('.order-line'),pack=row?.querySelector('[data-line-field="pack"]');if(!pack)return;const product=findProduct(input.value);if(!pack.value||pack.dataset.autoFor){pack.value=product?.unitsPerPick||'';if(product?.unitsPerPick)pack.dataset.autoFor=refKey(input.value);else delete pack.dataset.autoFor;}}
function renderOrderLines(){
  const el=document.querySelector('#order-lines');if(!el)return;
  el.innerHTML=state.orderLines.map((l,i)=>{
    const control=(key,label,type,placeholder='')=>`<div class="input-voice"><input id="order-line-${i}-${key}" data-line-field="${key}" type="${type}" ${type==='number'?`min="${key==='pickingOverride'?0:1}" step="1" inputmode="numeric"`: 'autocomplete="off" spellcheck="false"'} aria-label="${label} ligne ${i+1}" value="${esc(l[key]??'')}" placeholder="${placeholder}"><button type="button" class="mic-btn" data-action="dictate" data-target="order-line-${i}-${key}" data-code="${key==='sku'?1:0}" aria-label="Dicter ${label.toLowerCase()} ligne ${i+1}">${icon('mic')}</button></div>`;
    return `<fieldset class="order-line" data-index="${i}"><legend>Ligne ${i+1}</legend><button class="icon-button" type="button" data-action="remove-order-line" data-index="${i}" aria-label="Supprimer la ligne ${i+1}">${icon('close')}</button><div class="form-grid"><div class="field"><label for="order-line-${i}-sku">Référence</label>${control('sku','Référence','text','Référence')}</div><div class="field"><label for="order-line-${i}-quantity">Quantité d’articles</label>${control('quantity','Quantité','number')}</div><div class="field"><label for="order-line-${i}-pack">Unités par prise</label>${control('pack','Unités par prise','number','Inconnu')}</div><div class="field"><label for="order-line-${i}-pickingOverride">Pickings manuels (facultatif)</label>${control('pickingOverride','Pickings manuels','number','Auto')}</div></div></fieldset>`;
  }).join('');
}
function updateOrderEstimate(){const el=document.querySelector('#order-estimate');if(!el)return;try{const lines=readOrderLines().filter(l=>l.sku.trim()&&l.quantity!=='');if(!lines.length){el.innerHTML='<p class="hint section-gap">Ajoutez une référence et une quantité pour calculer les prises.</p>';return;}const e=estimateLines(lines);el.innerHTML=`<div class="calc-result"><strong>${fmt(e.total)}</strong><div><p><b>${e.unknown?'Estimation minimale':'Pickings calculés'}</b> · ${lines.length} référence(s)</p><p>${e.unknown?`${e.unknown} ligne(s) sans conditionnement : fourchette de ${fmt(e.minimum)} à ${fmt(e.maximum)} prises au total. Une prise minimale par ligne inconnue.`:'Toutes les lignes disposent d’un conditionnement ou d’un nombre de prises saisi.'}</p></div></div>`;}catch(e){el.innerHTML=`<p class="error-message">${esc(e.message)}</p>`;}}

async function stableFile(file){let timer;try{const bytes=await Promise.race([file.arrayBuffer(),new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error('La photo n’est pas accessible. Choisissez-la à nouveau depuis la galerie.')),10000);})]);return new File([bytes],file.name||'photo.jpg',{type:file.type||'image/jpeg'});}catch{throw Error('La photo n’est pas lisible. Choisissez-la à nouveau depuis la galerie ou saisissez les lignes manuellement.');}finally{clearTimeout(timer);}}
async function attachPhoto(file,kind='photo'){const stable=await stableFile(file);const id=await Store.storeFile(stable,stable.name,kind);await Store.save('documents',{id,name:stable.name,kind,createdAt:isoNow()},'Document ajouté');return id;}
async function handleSubmit(form){
  if(formSaving)return;const name=form.dataset.form;const d=dataObject(form),id=form.dataset.id||undefined;const button=form.querySelector('[type="submit"]');formSaving=true;if(button)button.disabled=true;
  try{
    switch(name){
      case 'onboarding':await Store.save('preferences',{...Store.settings(),id:'main',name:d.name.trim(),goal:number(d.goal,{min:1,integer:true}),profile:state.formRole,beginner:true,welcomed:true},'Espace configuré');await Ops.clearDraft(form);closeModal();toast('Votre espace est prêt.');break;
      case 'settings':await Store.save('preferences',{...Store.settings(),id:'main',name:d.name.trim(),goal:number(d.goal,{min:1,integer:true}),profile:d.profile,beginner:!!d.beginner},'Préférences modifiées');toast('Réglages enregistrés.');break;
      case 'google-settings':Sync.saveConnection({clientId:d.clientId.trim(),spreadsheetId:d.spreadsheetId.trim().replace(/^.*\/d\/([^/]+).*$/,'$1')});toast('Connexion configurée. Vous pouvez connecter votre compte.');break;
      case 'barcode':await Features.generateBarcode(d.value.trim(),d.format,!!d.stars);break;
      case 'batch-codes':Features.createBatch(d.values,!!d.stars);break;
      case 'lookup-product':await Features.lookupProduct(d.code);break;
      case 'pending':{
        const previous=id?getRaw('pending',id):{};const orderNumber=refKey(d.orderNumber),sku=refKey(d.sku),location=refKey(d.location);const quantity=number(d.quantity,{min:1,integer:true}),received=number(d.received||0,{integer:true});
        if(received>quantity)throw Error('La quantité reçue ne peut pas dépasser la quantité manquante.');
        if(!id&&Store.list('pending').some(p=>p.status!=='done'&&refKey(p.orderNumber)===orderNumber&&refKey(p.sku)===sku&&refKey(p.location)===location))throw Error('Cette référence est déjà en attente pour cette commande. Modifiez sa fiche existante.');
        await Store.save('pending',{...previous,id,orderNumber,sku,location,quantity,received,assignee:d.assignee.trim(),priority:d.priority,status:d.status,notes:d.notes.trim(),createdAt:previous?.createdAt||isoNow(),waitingSince:previous?.waitingSince||previous?.createdAt||previous?.updatedAt||isoNow()},id?'Attente de réassort modifiée':'Manquant enregistré');await Ops.clearDraft(form);closeModal();toast('Suivi de réassort enregistré.');break;
      }
      case 'product':{
        const previous=id?products().find(p=>p.id===id):{};const sku=refKey(d.sku);if(!id&&findProducts(sku).length)throw Error('Cette référence existe déjà. Retrouvez-la dans le catalogue pour compléter sa fiche.');
        const pack=number(d.unitsPerPick,{min:1,integer:true,optional:true});const photo=form.querySelector('[name="productPhoto"]')?.files[0];const photoId=d.removePhoto?null:photo?await attachPhoto(await compressProductPhoto(photo),'product-photo'):state.draftProductPhotoId||previous.photoId||null;
        const location=refKey(d.location),locations=[...new Set([location,...(previous.locations||[]).filter(l=>l!==previous.location)].filter(Boolean))];
        const record={...previous,id:id||uid(),sku,barcode:d.barcode.trim(),name:d.name.trim(),familyId:d.familyId,unitsPerPick:pack,location,locations,aliases:d.aliases?.trim()||'',notes:d.notes.trim(),photoId,namePending:false};
        const oldPack=Store.list('packagings').find(p=>refKey(p.sku)===sku);await Store.saveBatch([{type:'products',record},{type:'packagings',record:{id:oldPack?.id||'pack-'+sku,sku,unitsPerPick:pack}}],id?'Référence complétée':'Référence créée');await Ops.resolveUnknowns(record);await Ops.clearDraft(form);closeModal();toast('Référence enregistrée. Les calculs passés ne sont pas modifiés automatiquement.');break;
      }
      case 'family':{const rid=id||uid();validateFamilyParent(rid,d.parentId,families(true));const old=id?families(true).find(f=>f.id===id):{};await Store.save('families',{...old,id:rid,name:d.name.trim(),parentId:d.parentId||null,active:!!d.active},id?'Famille modifiée':'Famille créée');await Ops.clearDraft(form);closeModal();toast('Famille enregistrée.');break;}
      case 'location':{const location=refKey(d.name);if(Store.list('locations').some(l=>l.id!==id&&refKey(l.name)===location))throw Error('Cet emplacement existe déjà.');await Store.save('locations',{id,...d,name:location},id?'Emplacement modifié':'Emplacement créé');await Ops.clearDraft(form);closeModal();toast('Emplacement enregistré.');break;}
      case 'movement':{if(refKey(d.from)===refKey(d.to))throw Error('Les emplacements de départ et d’arrivée doivent être différents.');await Store.save('movements',{sku:refKey(d.sku),from:refKey(d.from),to:refKey(d.to),quantity:number(d.quantity,{min:1,integer:true}),reason:d.reason,notes:d.notes.trim(),date:localDate()},'Transfert de stock noté');await Ops.clearDraft(form);closeModal();toast('Trace du transfert enregistrée.');break;}
      case 'count':await Store.save('counts',{id,session:d.session.trim(),date:d.date,location:refKey(d.location),sku:refKey(d.sku),counted:number(d.counted,{integer:true}),expected:number(d.expected,{integer:true,optional:true}),kind:d.kind,notes:d.notes.trim()},id?'Comptage corrigé':'Comptage enregistré');await Ops.clearDraft(form);closeModal();toast('Comptage enregistré.');break;
      case 'replenishment':{const min=number(d.min,{integer:true}),economic=number(d.economic,{integer:true}),max=number(d.max,{integer:true});if(!(min<=economic&&economic<=max))throw Error('Respectez l’ordre : minimum ≤ économique ≤ maximum.');await Store.save('replenishments',{id,sku:refKey(d.sku),location:refKey(d.location),min,economic,max,current:number(d.current,{integer:true,optional:true}),notes:d.notes.trim()},id?'Seuils de réassort modifiés':'Seuils de réassort notés');await Ops.clearDraft(form);closeModal();toast('Seuils enregistrés.');break;}
      case 'issue':{const old=id?getRaw('issues',id):{};const f=form.querySelector('[name="photo"]').files[0];const photoId=f?await attachPhoto(f):old?.photoId;await Store.save('issues',{...old,id,kind:d.kind,sku:refKey(d.sku),location:refKey(d.location),expected:number(d.expected,{integer:true,optional:true}),found:number(d.found,{integer:true,optional:true}),assignee:d.assignee.trim(),status:d.status,notes:d.notes.trim(),photoId},id?'Signalement mis à jour':'Écart signalé');await Ops.clearDraft(form);closeModal();toast('Signalement enregistré.');break;}
      case 'day-correction':{const old=Store.list('days').find(r=>r.date===d.date);await Store.save('days',{...old,id:old?.id||'day-'+d.date,date:d.date,manualTotal:number(d.manualTotal,{integer:true}),reason:d.reason.trim()},'Total journalier corrigé');state.date=d.date;await Ops.clearDraft(form);closeModal();render();toast('Total corrigé. La valeur précédente reste dans l’historique.');break;}
      case 'order':{
        const rows=readOrderLines();if(!rows.length)throw Error('Ajoutez au moins une ligne.');
        if(rows.some(l=>!l.sku.trim()||l.quantity===''))throw Error('Chaque ligne doit avoir une référence et une quantité. Supprimez les lignes vides.');
        const numberValue=refKey(d.number);if(Store.list('orders').some(o=>o.id!==id&&refKey(o.number)===numberValue))throw Error('Cette commande est déjà enregistrée. Modifiez sa fiche pour ajouter ses autres pages et éviter un double comptage.');
        const e=estimateLines(rows.map(l=>({...l,sku:refKey(l.sku)})));const previous=state.selectedOrder;const photoIds=[...new Set([...(previous?.photoIds||[]),...(state.draftPhotoIds||[])])];for(const photo of state.orderPhotos)photoIds.push(await attachPhoto(photo));
        await Store.save('orders',{...previous,id,number:numberValue,date:d.date,lines:e.lines,total:e.total,rangeMax:e.maximum,unknownLines:e.unknown,calculationStatus:e.status,status:'completed',notes:d.notes.trim(),photoIds,reviewed:true},id?'Commande corrigée':'Commande terminée enregistrée');state.date=d.date;await Ops.clearDraft(form);closeModal();render();toast(e.unknown?'Commande enregistrée avec une estimation à affiner.':'Commande enregistrée.');break;
      }
      case 'pending-partial':{const r=getRaw('pending',id),received=number(d.received,{integer:true});if(received>r.quantity)throw Error('Le reçu ne peut pas dépasser la quantité manquante.');await Store.save('pending',{...r,received,status:received===r.quantity?'received':received===0?'waiting':'partial'},'Réception partielle mise à jour');await Ops.clearDraft(form);closeModal();toast('Réception mise à jour.');break;}
      case 'import-products':{const text=d.text;const lines=text.split(/\r?\n/).map(l=>l.trim()).filter(Boolean);if(!lines.length||lines.length>500)throw Error('Importez de 1 à 500 lignes à la fois.');let added=0;for(const line of lines){const [sku,name,barcode='',pack='']=line.split(';').map(s=>s.trim());if(/^(référence|reference|sku)$/i.test(sku))continue;if(!sku||!name)throw Error('Chaque ligne doit contenir référence ; nom ; EAN ; unités par prise.');number(pack,{min:1,integer:true,optional:true});}
        for(const line of lines){const [sku,name,barcode='',pack='']=line.split(';').map(s=>s.trim());if(/^(référence|reference|sku)$/i.test(sku))continue;const existing=findProduct(sku);const unitsPerPick=number(pack,{min:1,integer:true,optional:true});await Store.save('products',{...existing,sku:refKey(sku),name,barcode,unitsPerPick},'Référence importée');if(pack){const old=Store.list('packagings').find(p=>refKey(p.sku)===refKey(sku));await Store.save('packagings',{id:old?.id||'pack-'+refKey(sku),sku:refKey(sku),unitsPerPick},'Conditionnement importé');}added++;}await Ops.clearDraft(form);closeModal();toast(`${added} référence(s) importée(s).`);break;}
    }
  }catch(error){formError(form,error);}finally{formSaving=false;if(button?.isConnected)button.disabled=false;}
}

async function seedDemo(){if(Store.list('orders').length)return;await Store.save('preferences',{id:'main',name:'Démo',profile:'preparer',goal:1800,beginner:true,welcomed:true},'Démonstration ouverte');for(let i=4;i>=0;i--){const date=new Date();date.setDate(date.getDate()-i);const day=localDate(date);await Store.save('orders',{id:'demo-order-'+i,number:'DEMO-'+(100+i),date:day,lines:[{sku:'DEMO-STYLO',quantity:4,pack:1}],total:[1230,1510,1640,1390,1720][i],calculationStatus:i===1?'estimated':'verified',status:'completed',notes:'Exemple fictif de démonstration'},'Exemple de commande');}
  await Store.save('pending',{id:'demo-pending-1',orderNumber:'DEMO-205',sku:'DEMO-CARNET',location:'20-04-B',quantity:12,received:0,status:'waiting',assignee:'Gestionnaire de stock',priority:'normal',notes:'Exemple fictif de référence manquante.'},'Exemple de manquant');await Store.save('products',{id:'demo-product',sku:'DEMO-CARNET',name:'Carnet de démonstration',unitsPerPick:4},'Exemple de produit');await Store.save('locations',{id:'demo-location',name:'20-04-B',aisle:'20',level:'B',zone:'Picking',notes:'Exemple de casier'},'Exemple d’emplacement');}
async function toggleDemo(on){await Ops.persistDraft();Features.stopCamera();closeModal();sessionStorage.setItem('ek-demo',on?'1':'0');await Store.openStore(on);if(on)await seedDemo();navigate('home');toast(on?'Démonstration ouverte. Vos vraies données sont séparées.':'Vous avez retrouvé vos données de travail.');}

async function handleAction(button){const action=button.dataset.action,id=button.dataset.id;switch(action){
  case 'close-dialog':closeModal();break;
  case 'ops-unknowns':navigate('unknowns');break;case 'ops-journal':navigate('journal');break;
  case 'receipt':Ops.openReceipt();break;
  case 'camera-torch':await Features.toggleTorch();break;
  case 'onboard-role':{const name=document.querySelector('#f-name')?.value,goal=document.querySelector('#f-goal')?.value;welcome(button.dataset.role);if(name)document.querySelector('#f-name').value=name;if(goal)document.querySelector('#f-goal').value=goal;break;}
  case 'choose-role':welcome(Store.settings().profile);break;
  case 'dictate':Features.dictate(button);break;
  case 'chart-range':state.chartDays=Number(button.dataset.days);render();break;
  case 'previous-date':case 'next-date':{const d=new Date(state.date+'T12:00:00');d.setDate(d.getDate()+(action==='next-date'?1:-1));state.date=localDate(d);render();break;}
  case 'new-pending':pendingForm();break;case 'edit-pending':pendingForm(getRaw('pending',id));break;
  case 'pending-received':{const row=getRaw('pending',id);await Store.save('pending',{...row,status:'received',received:row.quantity},'Réassort reçu');toast('Réassort reçu. Vous pourrez clôturer la commande une fois sa préparation terminée.');break;}
  case 'pending-done':{const row=getRaw('pending',id);await Store.save('pending',{...row,status:'done'},'Commande en attente clôturée');toast('Commande marquée terminée. Ajoutez-la au suivi des pickings si nécessaire.');break;}
  case 'pending-partial':{const r=getRaw('pending',id);modalForm('pending-partial',field('received','Quantité reçue au total',r.received??0,{type:'number',required:true,full:true,hint:`Quantité manquante initiale : ${r.quantity}`}),{id,title:'Réception partielle'});break;}
  case 'new-product':productForm();break;case 'edit-product':{const p=products().find(p=>p.id===id);if(!p)throw Error('Référence introuvable.');productForm(p);break;}
  case 'new-product-from-scan':productForm({sku:button.dataset.code,barcode:button.dataset.code});break;
  case 'new-family':familyForm();break;case 'edit-family':familyForm(families(true).find(f=>f.id===id));break;
  case 'new-location':locationForm();break;case 'edit-location':locationForm(getRaw('locations',id));break;
  case 'new-movement':movementForm();break;
  case 'new-count':countForm();break;case 'empty-check':countForm({},true);break;case 'edit-count':countForm(getRaw('counts',id));break;
  case 'new-replenishment':replenishmentForm();break;case 'edit-replenishment':replenishmentForm(getRaw('replenishments',id));break;
  case 'new-issue':issueForm();break;case 'edit-issue':issueForm(getRaw('issues',id));break;
  case 'new-order':orderForm();break;case 'edit-order':orderForm(getRaw('orders',id));break;
  case 'add-order-line':state.orderLines=readOrderLines();state.orderLines.push({sku:'',quantity:'',pack:'',pickingOverride:''});renderOrderLines();break;
  case 'remove-order-line':state.orderLines=readOrderLines();state.orderLines.splice(Number(button.dataset.index),1);renderOrderLines();updateOrderEstimate();break;
  case 'recalculate-order':updateOrderEstimate();break;
  case 'ocr-example':{if(!Store.isDemo())throw Error('Cet exercice est réservé à la démonstration.');const r=await fetch('assets/tutorial-commande.png');const b=await r.blob();await readOrderPhotos([new File([b],'exemple-commande.png',{type:'image/png'})]);break;}
  case 'parse-order-text':{const text=document.querySelector('#order-raw-text').value;const parsed=parseOrderText(text);if(!parsed.lines.length)throw Error('Aucune ligne reconnue. Utilisez le format référence ; quantité ; unités par prise, ou saisissez les lignes manuellement.');const existing=readOrderLines().filter(l=>l.sku||l.quantity);state.orderLines=existing.concat(parsed.lines.map(l=>({...l,pack:l.pack||findProduct(l.sku)?.unitsPerPick||''})));renderOrderLines();updateOrderEstimate();const n=document.querySelector('[data-form="order"] [name="number"]');if(!n.value&&parsed.orderNumber)n.value=parsed.orderNumber;toast('Lignes proposées. Vérifiez chaque référence et chaque quantité.');break;}
  case 'correct-day':dayCorrection();break;
  case 'compare-codes':await Features.compareCodes();break;
  case 'test-barcode-result':{const stars=button.dataset.stars==='1';await Store.save('preferences',{...Store.settings(),id:'main',barcodeDefaultStars:stars,honeywellTestAt:isoNow()},'Résultat de lecture Honeywell renseigné');state.codeStars=stars;closeModal();toast('Votre résultat de test est enregistré. Cette variante est proposée par défaut.');break;}
  case 'batch-codes':Features.batchDialog();break;case 'batch-pdf':await Features.batchPDF();break;
  case 'print':window.print();break;
  case 'code-fullscreen':await document.querySelector('#barcode-stage')?.requestFullscreen?.();break;
  case 'code-svg':case 'code-png':case 'code-pdf':await Features.exportCode(action.split('-')[1]);break;
  case 'code-favourite':{if(!state.generated)throw Error('Générez un code.');const g=state.generated;const old=Store.list('codes').find(c=>c.id===g.id)||Store.list('codes').find(c=>c.value===g.value&&c.format===g.format&&c.stars===g.stars);await Store.save('codes',{...old,value:g.value,format:g.format,stars:g.stars,favourite:!old?.favourite},old?.favourite?'Code retiré des favoris':'Code ajouté aux favoris');toast(old?.favourite?'Favori retiré.':'Code ajouté aux favoris.');break;}
  case 'unfavourite-code':{const r=getRaw('codes',id);await Store.save('codes',{...r,favourite:false},'Code retiré des favoris');break;}
  case 'reuse-code':{const r=getRaw('codes',id);await Features.generateBarcode(r.value,r.format,r.stars);render();break;}
  case 'code-from-product':navigate('codes');await Features.generateBarcode(button.dataset.code);render();break;
  case 'start-camera':await Features.startCamera();break;case 'next-camera':await Features.nextCamera();break;case 'stop-camera':Features.stopCamera();break;
  case 'scan-example':{if(!Store.isDemo())throw Error('Cet exercice est réservé à la démonstration.');const r=await fetch('assets/tutorial-code128.png');await Features.scanPhoto(await r.blob());break;}
  case 'view-photo':await Features.viewPhoto(id);break;
  case 'backup':{toast('Préparation de votre sauvegarde…');const data=await Store.exportData();jsonDownload(data,`ek-logistique-${localDate()}${Store.isDemo()?'-demo':''}.json`);toast('Sauvegarde exportée.');break;}
  case 'restore':restoreInput=document.createElement('input');restoreInput.type='file';restoreInput.accept='.json,application/json';restoreInput.onchange=async()=>{try{const file=restoreInput.files[0];if(!file)return;const data=JSON.parse(await file.text());if(!confirm('Importer cette sauvegarde et la fusionner avec les données de cet appareil ?'))return;await Store.importData(data);toast('Sauvegarde importée et fusionnée.');}catch(e){toast(e.message,true);}};restoreInput.click();break;
  case 'remove-record':{const type=button.dataset.type,row=getRaw(type,id);modal('Retirer cette fiche ?',`<p class="dialog-intro">La fiche ${esc(recordLabel(row))} sera retirée des listes et des totaux. Ses anciennes valeurs restent dans l’historique.</p><div class="form-actions">${btn('Annuler','close-dialog')}${btn('Retirer la fiche','confirm-remove','trash','danger',`data-type="${esc(type)}" data-id="${esc(id)}"`)}</div>`);break;}
  case 'confirm-remove':{const type=button.dataset.type,row=getRaw(type,id);await Store.save(type,{...row,deleted:true},'Fiche retirée');closeModal();toast('Fiche retirée. L’historique est conservé.');break;}
  case 'event-detail':{const ev=Store.getEvents().find(e=>e.id===id);const labels={number:'Commande',orderNumber:'Commande',sku:'Référence',name:'Dénomination',date:'Journée',location:'Emplacement',from:'Départ',to:'Arrivée',quantity:'Quantité',received:'Quantité reçue',unitsPerPick:'Unités par prise',manualTotal:'Total corrigé',total:'Pickings calculés',reason:'Motif',notes:'Précisions',status:'Statut',assignee:'Personne sollicitée',min:'Stock minimum',economic:'Niveau économique',max:'Stock maximum',current:'Dernier constat',counted:'Quantité comptée',expected:'Quantité attendue',found:'Quantité trouvée',session:'Session',kind:'Type',value:'Texte du code',format:'Format du code',stars:'Étoiles dans les données',deleted:'Fiche retirée',lines:'Lignes de la commande'};const value=(key,v)=>key==='lines'?(v||[]).map(l=>`${l.sku} : ${l.quantity} article(s), ${l.pack||'?'} unité(s) par prise, ${l.pickings??'?'} picking(s)`).join('\n'):typeof v==='boolean'?(v?'Oui':'Non'):String(v??'—');modal('Détail de l’action',`<p class="dialog-intro">${esc(ev.action)} · ${timestampLabel(ev.updatedAt)} · ${esc(ev.actor)}</p><dl class="record-detail">${Object.entries(ev.record).filter(([k])=>labels[k]).map(([k,v])=>`<div><dt>${esc(labels[k])}</dt><dd class="wrap">${esc(value(k,v)).replace(/\n/g,'<br>')}</dd></div>`).join('')}</dl><p class="hint section-gap">Cette fiche montre la valeur enregistrée à cette date. Les autres versions restent consultables dans l’historique.</p>`);break;}
  case 'share-issue':{const r=getRaw('issues',id);const text=`Écart de stock — ${r.kind}\nRéférence : ${r.sku||'—'}\nEmplacement : ${r.location||'—'}\nAttendu : ${r.expected??'—'} / Trouvé : ${r.found??'—'}\n${r.notes||''}`;modal('Préparer le partage du signalement',`<p class="dialog-intro">Copiez ces informations pour les transmettre avec votre outil habituel.</p><textarea id="share-text" rows="8" readonly>${esc(text)}</textarea><div class="form-actions">${btn('Copier le texte','copy-share','link','primary')}</div>`);break;}
  case 'copy-share':{const t=document.querySelector('#share-text');try{await navigator.clipboard.writeText(t.value);toast('Texte copié.');}catch{t.select();toast('Sélectionnez puis copiez le texte.');}break;}
  case 'catalogue-prev':state.page=Math.max(0,state.page-1);render();break;case 'catalogue-next':state.page++;render();break;
  case 'import-products':modalForm('import-products',field('text','Référence ; nom ; EAN ; unités par prise','',{textarea:true,full:true,required:true,rows:9,hint:'Une ligne par produit, séparateur « ; ». Les cellules de conditionnement peuvent rester vides.'}),{title:'Importer un catalogue CSV',submit:'Importer les lignes',intro:'Les références existantes seront complétées. Relisez le contenu avant de l’importer.'});break;
  case 'enter-demo':await toggleDemo(true);break;case 'exit-demo':await toggleDemo(false);break;
  case 'google-settings':navigate('settings');document.querySelector('#google-settings')?.scrollIntoView({behavior:'smooth'});break;
  case 'connect-google':{const f=document.querySelector('[data-form="google-settings"]');if(f){const data=dataObject(f);Sync.saveConnection({clientId:data.clientId.trim(),spreadsheetId:data.spreadsheetId.trim().replace(/^.*\/d\/([^/]+).*$/,'$1')});}await Sync.connect();break;}
  case 'sync':await Sync.sync();break;case 'disconnect-google':Sync.disconnect();render();break;
  case 'create-database':if(!Sync.connected())throw Error('Connectez d’abord votre compte Google.');if(confirm('Créer une nouvelle base Google Sheets et l’utiliser pour les prochaines synchronisations ? Votre base précédente sera conservée.')){await Sync.createDatabase();await Sync.sync();render();toast('Nouvelle base créée.');}break;
  case 'cache-ocr':await Features.cacheOCR();break;
  case 'install-app':if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;}else modal('Installer EK Logistique',`<div class="steps"><div class="step"><div>Ouvrez l’application dans Chrome sur votre téléphone, depuis son adresse HTTPS.</div></div><div class="step"><div>Touchez le menu <b>⋮</b> puis <b>Ajouter à l’écran d’accueil</b> ou <b>Installer l’application</b>.</div></div><div class="step"><div>Ouvrez l’icône EK Logistique. La première ouverture prépare les outils disponibles hors ligne.</div></div></div><p class="hint section-gap">Sur iPhone, utilisez Safari → Partager → Sur l’écran d’accueil.</p>`);break;
  case 'quickhelp':case 'help-code':case 'help-pending':case 'help-pickings':case 'help-scan':case 'help-stock':case 'help-backup':showHelp(action);break;
  default:if(action.startsWith('export-'))exportSection(action.slice(7));
}}

function showHelp(action){const map={
  'help-code':['Créer un code-barres',['Saisissez la référence telle qu’elle apparaît, en gardant les zéros du début.','Touchez Générer le code. Vérifiez le texte affiché sous les barres.','Agrandissez le code pour le scanner avec votre terminal ou exportez-le en image/PDF.','Testez les variantes avec et sans étoiles avant de choisir le réglage utilisé sur le Honeywell.']],
  'help-pending':['Suivre une commande en attente',['Créez une fiche avec le numéro de commande, la référence manquante et le casier.','Quand le réassort arrive, touchez Reçu. Si une partie manque encore, indiquez la quantité reçue dans Partiel.','Reprenez votre préparation. Quand elle est terminée, touchez Commande terminée.','La fiche passe dans les commandes terminées du suivi des attentes. Ajoutez-la séparément aux pickings pour la compter.']],
  'help-pickings':['Calculer vos pickings',['Ajoutez une commande et choisissez sa date de réalisation.','Photographiez la feuille ou saisissez chaque référence et la quantité d’articles.','Renseignez le nombre d’unités par prise si vous le connaissez. Exemple : 12 articles par lots de 4 donnent 3 prises.','Relisez les lignes puis enregistrez. Les conditionnements manquants sont signalés et le total reste estimatif.','Pour un chiffre donné par Adrien, corrigez le total de la date concernée. L’ancienne valeur restera dans l’historique.']],
  'help-scan':['Reconnaître un produit',['Ouvrez Scanner un produit puis autorisez la caméra. Vous pouvez aussi choisir une photo.','Cadrez le code entier, sans reflet, et restez immobile.','Le code est recherché dans vos références et dans le catalogue public Draeger Paris.','S’il existe plusieurs correspondances, vérifiez le nom. Si aucune n’est fiable, utilisez la recherche Web ou créez une fiche manuellement.']],
  'help-stock':['Compléter votre catalogue',['Recherchez un SKU, un EAN ou une désignation dans le catalogue.','Ouvrez la fiche pour indiquer son conditionnement et ses repères d’emplacement.','Créez ou modifiez les familles depuis l’onglet Familles.','Les mouvements, comptages et écarts servent au suivi personnel. Les opérations officielles restent à faire dans Velocity.']],
  'help-backup':['Sauvegarder votre travail',['Les saisies sont enregistrées automatiquement dans ce navigateur.','Dans Réglages, exportez régulièrement une sauvegarde JSON. Elle inclut les photos et l’historique.','Pour Google Sheets, configurez la connexion puis touchez Connecter mon compte et Synchroniser.','Pour changer d’appareil, connectez la même base Google ou importez votre sauvegarde JSON.']]};
  if(action==='quickhelp'){const route=state.route;action=route==='codes'?'help-code':route==='pending'?'help-pending':route==='orders'?'help-pickings':route==='scan'?'help-scan':route==='settings'?'help-backup':'help-stock';}
  const [title,steps]=map[action]||map['help-code'];modal(title,`<div class="steps">${steps.map(s=>`<div class="step"><div>${esc(s)}</div></div>`).join('')}</div><div class="form-actions">${btn('J’ai compris','close-dialog','check','primary')}</div>`);}
function exportSection(kind){
  if(kind==='day'){const orders=Store.list('orders').filter(o=>o.date===state.date),s=dailyStats(state.date,Store.list('orders'),Store.list('days'),Store.settings().goal);const lines=[{heading:true,text:'Bilan de la journée'},`Date : ${dateLabel(state.date,{day:'numeric',month:'long',year:'numeric'})}`,`Pickings retenus : ${s.hasData?fmt(s.total):'non renseignés'} / objectif ${fmt(s.goal)}`,`Commandes terminées : ${s.commands}`,`Qualité du total : ${s.status==='estimated'?'estimation à affiner':s.status==='corrected'?'correction manuelle':'calcul avec règles renseignées'}`,s.correction?`Correction : ${s.correction.reason}`:'',...orders.flatMap(o=>[{heading:true,text:'Commande '+o.number},`${o.lines.length} ligne(s) - ${o.total} picking(s) - ${o.calculationStatus==='estimated'?'estimation':'règles renseignées'}`,...o.lines.map(l=>`${l.sku} : ${l.quantity} article(s), ${l.pack||'?'} unité(s) par prise, ${l.pickings??'?'} prise(s).`)])];pdfReport('Suivi des commandes et pickings',lines.filter(Boolean),`pickings-${state.date}.pdf`);return;}
  let headers,rows;
  if(kind==='products'){headers=['Référence','Dénomination','EAN','Famille','Unités par prise','Emplacement'];rows=products().map(p=>[p.sku,p.name,p.barcode,p.familyId,p.unitsPerPick,(p.locations?.length?p.locations:[p.location]).filter(Boolean).join(' | ')]);}
  else if(kind==='history'){headers=['Date','Auteur','Action','Type','Identifiant','Données'];rows=Store.getEvents().map(e=>[e.updatedAt,e.actor,e.action,e.type,e.record.id,JSON.stringify(e.record)]);}
  else if(kind==='pending'){headers=['Commande','Référence','Casier','Manquant','Reçu','Statut','Personne','Notes'];rows=Store.list('pending').map(r=>[r.orderNumber,r.sku,r.location,r.quantity,r.received,r.status,r.assignee,r.notes]);}
  else if(kind==='issues'){headers=['Date','Type','Référence','Emplacement','Attendu','Trouvé','Statut','Notes'];rows=Store.list('issues').map(r=>[r.updatedAt,r.kind,r.sku,r.location,r.expected,r.found,r.status,r.notes]);}
  else if(kind==='counts'){headers=['Session','Date','Référence','Emplacement','Attendu','Compté','Écart','Notes'];rows=Store.list('counts').map(r=>[r.session,r.date,r.sku,r.location,r.expected,r.counted,r.expected==null?'':r.counted-r.expected,r.notes]);}
  else if(kind==='movements'){headers=['Date','Référence','Départ','Arrivée','Quantité','Motif','Notes'];rows=Store.list('movements').map(r=>[r.updatedAt,r.sku,r.from,r.to,r.quantity,r.reason,r.notes]);}
  else return;
  download(new Blob([toCSV(headers,rows)],{type:'text/csv;charset=utf-8'}),`ek-${kind}-${localDate()}.csv`);toast('Export CSV prêt.');
}

async function handleFiles(input){const files=[...input.files];if(!files.length)return;
  if(input.dataset.fileAction==='scan-photo'){toast('Lecture du code sur la photo…');await Features.scanPhoto(files[0]);}
  if(input.dataset.fileAction==='font'){const f=await stableFile(files[0]);if(f.size>12e6)throw Error('Choisissez une police de moins de 12 Mo.');const id=await Store.storeFile(f,f.name,'font');await Store.save('preferences',{...Store.settings(),id:'main',fontId:id,fontName:f.name},'Police spécifique importée');toast('Police importée. Testez son fonctionnement avec le Honeywell.');}
  if(input.dataset.fileAction==='order-photos')await readOrderPhotos(files);
}
async function readOrderPhotos(files){const output=document.querySelector('#ocr-progress'),owner=document.querySelector('[data-form="order"]');for(const source of files){if(source.size>25e6)throw Error('Chaque photo doit faire moins de 25 Mo.');if(output)output.textContent='Préparation de la lecture…';let file=await stableFile(source);if(!owner?.isConnected)return;file=await editDocumentPhoto(file);if(!file)continue;if(!owner.isConnected)return;await Ops.saveDraftPhoto(file);try{const text=await Features.recognizePhoto(file,message=>{if(output?.isConnected)output.textContent=message;});if(!owner.isConnected)return;const raw=owner.querySelector('#order-raw-text');raw.value+=(raw.value?'\n\n':'')+text;await Ops.persistDraft();toast('Texte lu. Relisez-le puis extrayez les lignes.');}catch(e){if(output?.isConnected)output.textContent='La lecture automatique a échoué. La photo reste jointe ; vous pouvez saisir les lignes manuellement.';toast('Lecture automatique indisponible pour cette photo. Vous pouvez saisir les lignes manuellement.',true);}}}

document.addEventListener('click',event=>{const navigation=event.target.closest('[data-nav]');if(navigation){event.preventDefault();navigate(navigation.dataset.nav);return;}const button=event.target.closest('[data-action]');if(button&&!button.disabled){event.preventDefault();wrapAction(()=>handleAction(button));}});
document.addEventListener('submit',event=>{const form=event.target.closest('[data-form]');if(form){event.preventDefault();handleSubmit(form);}});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='camera-zoom'){wrapAction(()=>Features.setZoom(el.value));}else if(el.id==='scan-camera'){wrapAction(()=>Features.changeCamera(el.value));}else if(el.matches('[data-route-select]')){navigate(el.value);}else if(el.id==='day-select'){state.date=el.value||localDate();render();}else if(el.id==='view-filter'){state.filter=el.value;state.page=0;render();}else if(el.dataset.fileAction)wrapAction(()=>handleFiles(el));else if(el.matches('[data-line-field="sku"]')){fillLinePackaging(el);updateOrderEstimate();}});
let searchTimer;document.addEventListener('input',event=>{const el=event.target;if(el.matches('[data-filter-search]')){const v=el.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{state.query=v;state.page=0;render();},140);}if(el.matches('[data-line-field="sku"]'))fillLinePackaging(el);if(el.matches('[data-line-field="pack"]'))delete el.dataset.autoFor;if(el.matches('[data-line-field]'))updateOrderEstimate();});
document.querySelector('#dialog').addEventListener('cancel',()=>{Features.stopDictation();closeModal();});
window.addEventListener('online',()=>{updateNetwork();if(Sync.connected()&&!Store.isDemo())wrapAction(()=>Sync.sync());});window.addEventListener('offline',updateNetwork);
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)||'home'));
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});
window.addEventListener('ek-sync',event=>{updateNetwork();const d=event.detail;if(d.error)toast(d.message,true);else if(d.success)toast(d.message);});
document.addEventListener('visibilitychange',()=>{if(document.hidden){Features.stopCamera();Features.stopDictation();}});
Store.onChange(()=>{queueRender();clearTimeout(autoSyncTimer);if(Sync.connected()&&!Store.isDemo())autoSyncTimer=setTimeout(()=>{if(Store.pendingEvents().length)wrapAction(()=>Sync.sync());},1800);});

async function start(){
  try{await Store.openStore(sessionStorage.getItem('ek-demo')==='1');await loadCatalogue();if(Store.isDemo())await seedDemo();state.route=titles[location.hash.slice(1)]?location.hash.slice(1):'home';state.codeStars=Store.settings().barcodeDefaultStars||false;render();Ops.installOps({render,navigate,productForm,pendingForm,readOrderLines,renderOrderLines,updateOrderEstimate,restoreForm(d){const r=d.id&&d.form==='product'?products().find(p=>p.id===d.id):d.id?Store.get({order:'orders',pending:'pending',product:'products',issue:'issues',movement:'movements',count:'counts',replenishment:'replenishments'}[d.form],d.id):undefined;if(d.id&&(!r||r.deleted))throw Error('La fiche de ce brouillon a été retirée.');({order:()=>orderForm(r),pending:()=>pendingForm(r),product:()=>productForm(r),issue:()=>issueForm(r),movement:()=>movementForm(),count:()=>countForm(r),replenishment:()=>replenishmentForm(r)})[d.form]?.();}});if(!Store.settings().welcomed)welcome();if('serviceWorker' in navigator&&location.protocol!=='file:'&&location.hostname!=='terminal.local'){navigator.serviceWorker.register('sw.js',{updateViaCache:'none'}).then(reg=>{reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)toast('Une mise à jour est disponible. Fermez puis rouvrez l’application pour l’appliquer.');});});}).catch(()=>toast('Les outils hors ligne ne sont pas encore prêts. Vérifiez l’adresse de l’application.',true));}}
  catch(e){document.querySelector('#main').innerHTML=`<div class="card"><h1>Ouverture impossible</h1><p class="error-message">${esc(e.message)}</p><p class="small section-gap">Ouvrez l’application via le lanceur local ou son adresse HTTPS. Les fichiers ne doivent pas être ouverts directement en file://.</p><button class="btn primary section-gap" onclick="location.reload()">Réessayer</button></div>`;}
}
installMobileViewport();
start();


